def import_old_notes(apps, schema_editor):
    """把加這張表之前 Agent 自己下成功的每一手匯入：那時 AiNote 的思路裡已經存了模型與秒數。
    改由引擎代下的那幾手沒有記模型，無法匯入，所以舊紀錄算不出成功率。伺服器與電腦不明，留空；
    每一手的時間沒有存，用對局的開始時間。
    讀寫正在 migrate 的那個資料庫：設定裡除了 default（SQL Server）還有舊的 sqlite，不指定時一律讀寫 default。"""
    db = schema_editor.connection.alias
    AiNote = apps.get_model("arena", "AiNote")
    ModelRun = apps.get_model("arena", "ModelRun")
    runs = []
    for note in AiNote.objects.using(db).select_related("game"):
        narration = note.narration or {}
        if narration.get("source") == "agent" and narration.get("model") and narration.get("seconds") is not None:
            runs.append(ModelRun(created_at=note.game.created_at, kind="agent", game_type=note.game.game_type,
                                 game=note.game, index=note.index, model=narration["model"],
                                 seconds=narration["seconds"], outcome="ok"))
    ModelRun.objects.using(db).bulk_create(runs)


